-- GeoAIGames v2.1.0: recalibrated scoring scale and score-threshold unlocking.
--
-- Part 1 is generated by `prisma migrate diff` from the v2.0.0 schema to
-- prisma/schema.prisma. Part 2 adds CHECK constraints, a trigger and the new
-- reference data (scoring rules, unlock rules).
--
-- Additive for player data: two new columns, no player row is updated or
-- deleted. Historical game_results keep their exact score; the new
-- scoring_version is NULL on them, which means "original scale" and is
-- normalized (÷10) on read only. Docs: docs/SCORING_AND_PROGRESSION.md,
-- docs/DATABASE_SCHEMA.md ("20261118000000").
--
-- Deploy with the API stopped (see docs/DEVELOPMENT_GUIDE.md, "v2.1.0
-- deployment"): v2.0.0 code would read the new scoring rules without knowing
-- the new scale.

-- ===========================================================================
-- Part 1: columns (generated)
-- ===========================================================================

-- AlterTable
ALTER TABLE "user_profiles" ADD COLUMN     "level" INTEGER NOT NULL DEFAULT 1;

-- AlterTable
ALTER TABLE "game_results" ADD COLUMN     "scoring_version" SMALLINT;

-- ===========================================================================
-- Part 2: constraints, trigger, reference data (hand-written)
-- ===========================================================================

-- NOT NULL DEFAULT 1 instead of the usual NULLABLE column: every player has
-- a level, and PostgreSQL 11+ adds a constant default without rewriting the
-- table. Existing profiles start at 1; the backend raises them from their
-- existing unlocks on the next login or /levels call.
ALTER TABLE "user_profiles"
    ADD CONSTRAINT "user_profiles_level_positive" CHECK ("level" >= 1);

ALTER TABLE "game_results"
    ADD CONSTRAINT "game_results_scoring_version_positive" CHECK ("scoring_version" IS NULL OR "scoring_version" >= 1);

-- ---------------------------------------------------------------------------
-- Trigger: a player's level never goes down. Unlocks are permanent, so the
-- level derived from them can only grow, even if scoring or unlock rules
-- change later.
-- ---------------------------------------------------------------------------
CREATE FUNCTION "user_profiles_level_never_decreases"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."level" < OLD."level" THEN
        RAISE EXCEPTION 'user profile %: level cannot decrease (% -> %)', OLD."user_id", OLD."level", NEW."level"
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER "user_profiles_level_never_decreases"
    BEFORE UPDATE OF "level" ON "user_profiles"
    FOR EACH ROW EXECUTE FUNCTION "user_profiles_level_never_decreases"();

-- ---------------------------------------------------------------------------
-- Scoring rules (catalog). Sessions snapshot these when they start, so a
-- session already running keeps the rules it started with.
--
-- Level 1 Easy (Normal): 10 + min(5, streak - 1) per correct answer, max 135
--                        (the original 100 + min(50, ...) divided by 10).
-- Level 1 Hard:          20 + min(10, 2 × (streak - 1)), max 270 (2 × Easy).
-- Levels 2-5:            question base points (100) × pointScale 0.1, streak
--                        bonus min(5, streak - 1).
-- Only rows that still hold the seeded v2.0.0 rules are changed, so a manual
-- adjustment is never overwritten.
-- ---------------------------------------------------------------------------
UPDATE "game_modes" gm
   SET "config" = jsonb_set(gm."config", '{scoring}',
         '{"correctBase": 10, "streakBonusPerStep": 1, "streakBonusCap": 5, "wrong": 0, "maxScore": 135}'::jsonb),
       "updated_at" = now()
  FROM "games" g
 WHERE g."id" = gm."game_id" AND g."code" = 'telegram_country_quiz' AND gm."code" = 'easy'
   AND gm."config" -> 'scoring' ->> 'correctBase' = '100';

UPDATE "game_modes" gm
   SET "config" = jsonb_set(gm."config", '{scoring}',
         '{"correctBase": 20, "streakBonusPerStep": 2, "streakBonusCap": 10, "wrong": 0, "maxScore": 270}'::jsonb),
       "updated_at" = now()
  FROM "games" g
 WHERE g."id" = gm."game_id" AND g."code" = 'telegram_country_quiz' AND gm."code" = 'hard'
   AND gm."config" -> 'scoring' ->> 'correctBase' = '100';

UPDATE "game_modes" gm
   SET "config" = jsonb_set(gm."config", '{scoring}',
         (gm."config" -> 'scoring') || '{"pointScale": 0.1, "streakBonusPerStep": 1, "streakBonusCap": 5}'::jsonb),
       "updated_at" = now()
  FROM "games" g
 WHERE g."id" = gm."game_id" AND g."code" = 'explorer_levels'
   AND gm."config" -> 'scoring' ->> 'streakBonusPerStep' = '10'
   AND NOT (gm."config" -> 'scoring' ? 'pointScale');

-- ---------------------------------------------------------------------------
-- Unlock rules: cumulative lifetime score (all of the player's results,
-- normalized to the current scale) instead of completing the previous level.
-- Level 6 (15,000) is documented and will use the same rule type when it is
-- added. Only the seeded rules are replaced.
-- ---------------------------------------------------------------------------
UPDATE "game_levels" l
   SET "unlock_rule" = jsonb_build_object('type', 'total_score', 'min', t."min"),
       "updated_at" = now()
  FROM (VALUES (2, 1000), (3, 3000), (4, 6000), (5, 10000)) AS t("number", "min")
 WHERE l."number" = t."number"
   AND l."unlock_rule" = jsonb_build_object('type', 'level_completed', 'level', t."number" - 1);
